/* 15.12.81: 51 kapitelgebundene Deida-Verständnisfragen + 25 eigenständige Beratungstransferfragen. Fachliche Einordnung mit Kapitel- und Seitenverweis. */
window.BDDeidaKnowledge81=[{"id":"book81-ch01","chapterNo":1,"page":1,"chapter":"Kapitel 1 · Nicht auf den Abschluss warten","topic":"Nicht auf den Abschluss warten","track":"theory","question":"Wie versteht Deida die Erwartung, das Leben werde irgendwann „fertig“ sein?","answers":["Als Aufschub des eigenen lebendigen Handelns auf eine imaginäre spätere Phase.","Als notwendigen Schutz, bis Familie und Arbeit abgeschlossen sind.","Als Zeichen fehlender Bindung an die Partnerin.","Als rein finanzielles Problem ohne Bezug zur Lebenshaltung."],"explanation":"Deida fordert eine gegenwärtige Ausrichtung trotz bleibender Aufgaben; daraus folgt keine Pflicht, reale Verpflichtungen zu ignorieren.","source":"Deida (1997), Kapitel 1, Buchseite 1."},{"id":"book81-ch02","chapterNo":2,"page":3,"chapter":"Kapitel 2 · Mit offenem Herzen bei Schmerz bleiben","topic":"Mit offenem Herzen bei Schmerz bleiben","track":"theory","question":"Was fordert Deida bei Verletzung statt innerem Verschließen?","answers":["Den Schmerz wahrnehmen und zugleich kontaktfähig und handlungsfähig bleiben.","Verletzungen sofort mit körperlicher Nähe übergehen.","Jede Grenze aufgeben, um offen zu erscheinen.","Das eigene Empfinden unterdrücken, damit der andere ruhig bleibt."],"explanation":"Offenheit ist bei ihm eine Präsenzpraxis; professionell braucht es zusätzlich Sicherheit und Selbstschutz.","source":"Deida (1997), Kapitel 2, Buchseite 3."},{"id":"book81-ch03","chapterNo":3,"page":4,"chapter":"Kapitel 3 · Erwartungen des Vaters","topic":"Erwartungen des Vaters","track":"theory","question":"Worauf richtet Deida das Bild vom verstorbenen Vater?","answers":["Sich von verinnerlichten Erwartungen und Bewertungen des Vaters lösen.","Die reale Beziehung zum Vater unbedingt abbrechen.","Die Meinung des Vaters durch jene der Partnerin ersetzen.","Alle familiären Einflüsse als pathologisch verstehen."],"explanation":"Die Formulierung ist ein provokatives Gedankenexperiment über Autonomie, kein Trauer- oder Kontaktgebot.","source":"Deida (1997), Kapitel 3, Buchseite 4."},{"id":"book81-ch04","chapterNo":4,"page":5,"chapter":"Kapitel 4 · Die eigene Grenze kennen","topic":"Die eigene Grenze kennen","track":"theory","question":"Was beschreibt Deidas Begriff „edge“ am ehesten?","answers":["Die tatsächlich spürbare Grenze zwischen möglichem Wachstum und Vermeidung kennen.","Möglichst spektakuläre Risiken eingehen, unabhängig von Überforderung.","Schwierigkeiten vermeiden, um die innere Balance nicht zu stören.","Anderen eine größere Sicherheit vorspielen, als vorhanden ist."],"explanation":"Er kritisiert sowohl Selbstdarstellung als auch selbstschädigendes Überfordern.","source":"Deida (1997), Kapitel 4, Buchseite 5."},{"id":"book81-ch05","chapterNo":5,"page":7,"chapter":"Kapitel 5 · Tiefe Ausrichtung","topic":"Tiefe Ausrichtung","track":"theory","question":"Was meint Deida, wenn er die tiefste Erkenntnis zum Ausgangspunkt des Handelns macht?","answers":["Aus einer inneren Orientierung heraus handeln statt sich in wechselnden Aufgaben zu verlieren.","Alle Alltagsaufgaben als moralisch minderwertig ablehnen.","Nur in Meditation handeln und Entscheidungen aufschieben.","Die eigene innere Stimme als unfehlbares Wissen betrachten."],"explanation":"Deidas spirituelle Orientierung ist keine überprüfbare Diagnose und begründet keine Unfehlbarkeit.","source":"Deida (1997), Kapitel 5, Buchseite 7."},{"id":"book81-ch06","chapterNo":6,"page":9,"chapter":"Kapitel 6 · Nicht bloß gefallen wollen","topic":"Nicht bloß gefallen wollen","track":"theory","question":"Welche Unterscheidung trifft Deida beim Ändern der eigenen Meinung?","answers":["Eine neue Einsicht darf Entscheidungen ändern; bloße Anpassung gegen eigene Überzeugung untergräbt Authentizität.","Eine Frau darf niemals eine Entscheidung beeinflussen.","Eine Entscheidung muss aus Prinzip unverändert bleiben.","Kompromiss ist in jeder Beziehung ein Zeichen fehlender Führung."],"explanation":"Der Text betont eigenverantwortliche Entscheidungen nach ernsthaftem Zuhören.","source":"Deida (1997), Kapitel 6, Buchseite 9."},{"id":"book81-ch07","chapterNo":7,"page":11,"chapter":"Kapitel 7 · Lebensmission und Beziehung","topic":"Lebensmission und Beziehung","track":"theory","question":"Wie priorisiert Deida bei stark maskuliner Essenz die eigene Mission?","answers":["Die Lebensausrichtung soll nicht vollständig im Beziehungserleben aufgehen.","Beziehungspflichten dürfen grundsätzlich missachtet werden.","Alle Personen müssen eine Karriere vor Intimität stellen.","Die Partnerin muss sämtliche Fürsorgearbeit übernehmen."],"explanation":"Die Priorität ist Deidas normatives Rollenideal; andere Gewichtungen sind möglich.","source":"Deida (1997), Kapitel 7, Buchseite 11."},{"id":"book81-ch08","chapterNo":8,"page":12,"chapter":"Kapitel 8 · Ein Stück über die Komfortgrenze","topic":"Ein Stück über die Komfortgrenze","track":"theory","question":"Welche Herausforderung empfiehlt Deida im Umgang mit Angst?","answers":["Etwas über die aktuelle Grenze hinausgehen, ohne sich massiv zu überfordern.","Angst ignorieren, bis sie vollständig verschwunden ist.","Stets den maximalen Stress als Wachstum wählen.","Nur dann handeln, wenn keinerlei Unsicherheit mehr spürbar ist."],"explanation":"Er grenzt behutsames Wachstum ausdrücklich gegen Überforderung ab.","source":"Deida (1997), Kapitel 8, Buchseite 12."},{"id":"book81-ch09","chapterNo":9,"page":13,"chapter":"Kapitel 9 · Aus Liebe handeln","topic":"Aus Liebe handeln","track":"theory","question":"Was stellt Deida beim Motiv von Sexualität und Lebensgestaltung in den Mittelpunkt?","answers":["Liebe, Offenheit und das Geben eigener Gaben statt bloßer Bedürfnisbefriedigung.","Die Befriedigung eigener Impulse hat unabhängig von Zustimmung Vorrang.","Erotische Intensität ist der einzige Beweis für echte Liebe.","Sozialer Erfolg ist für ihn wichtiger als die Bedeutung einer Handlung."],"explanation":"Spirituelle Bildsprache darf keine Grenzüberschreitung legitimieren.","source":"Deida (1997), Kapitel 9, Buchseite 13."},{"id":"book81-ch10","chapterNo":10,"page":15,"chapter":"Kapitel 10 · Kritik durch Freunde","topic":"Kritik durch Freunde","track":"theory","question":"Welche Funktion weist Deida direkter Kritik von vertrauten Freunden zu?","answers":["Sie kann Selbsttäuschung aufdecken und persönliches Wachstum unterstützen.","Sie beweist automatisch, dass der Kritisierende recht hat.","Sie ist nur sinnvoll, wenn sie verletzend formuliert wird.","Sie ersetzt persönliche Reflexion durch Gehorsam."],"explanation":"Kritik kann wertvoll sein; ihre Berechtigung muss dennoch geprüft werden.","source":"Deida (1997), Kapitel 10, Buchseite 15."},{"id":"book81-ch11","chapterNo":11,"page":17,"chapter":"Kapitel 11 · Lebenszweck finden","topic":"Lebenszweck finden","track":"theory","question":"Welches Risiko verbindet Deida mit einer fehlenden eigenen Lebensausrichtung?","answers":["Sich überwiegend von äußeren Ereignissen treiben zu lassen.","Notwendigerweise alle Bindungen zu verlieren.","Nicht fähig zu sein, eine langfristige Arbeit auszuüben.","Dauerhaft keine emotionalen Bedürfnisse mehr zu haben."],"explanation":"Das ist Deidas existenzielles Entwicklungsmodell, keine klinische Kausaldiagnose.","source":"Deida (1997), Kapitel 11, Buchseite 17."},{"id":"book81-ch12","chapterNo":12,"page":18,"chapter":"Kapitel 12 · Lebensausrichtung verändern","topic":"Lebensausrichtung verändern","track":"theory","question":"Warum fordert Deida Bereitschaft, auch den eigenen Lebensplan aufzugeben?","answers":["Eine bisher sinnvolle Mission kann enden und einen neuen Abschnitt verlangen.","Wer eine Mission findet, soll sie unverändert bis zum Lebensende verfolgen.","Ein Richtungswechsel zeigt grundsätzlich mangelnde Disziplin.","Eine Partnerschaft muss beendet werden, sobald berufliche Interessen sich ändern."],"explanation":"Deida verbindet Hingabe an einen Zweck mit der Fähigkeit, ihn wieder loszulassen.","source":"Deida (1997), Kapitel 12, Buchseite 18."},{"id":"book81-ch13","chapterNo":13,"page":21,"chapter":"Kapitel 13 · Familie nicht als Ausrede","topic":"Familie nicht als Ausrede","track":"theory","question":"Was kritisiert Deida am Argument, die Familie verhindere jede eigene Berufung?","answers":["Dass Fürsorgepflichten manchmal als pauschale Entschuldigung für vermiedene Entscheidungen dienen.","Dass Kinder und Angehörige keinerlei berechtigte Bedürfnisse haben.","Dass persönliche Ziele nie mit familiären Pflichten vereinbar sind.","Dass eine Beziehung nur bei vollständiger Unabhängigkeit funktioniert."],"explanation":"Die Kritik an Ausreden hebt echte Sorgeverantwortung nicht auf.","source":"Deida (1997), Kapitel 13, Buchseite 21."},{"id":"book81-ch14","chapterNo":14,"page":23,"chapter":"Kapitel 14 · Nicht in Pflichten aufgehen","topic":"Nicht in Pflichten aufgehen","track":"theory","question":"Was soll nach Deida verhindern, dass der Alltag die Ausrichtung überdeckt?","answers":["Regelmäßige Rückbindung an Sinn und Präsenz statt ausschließlich Aufgaben abzuhaken.","Noch präzisere Haushaltslisten als einzige Form spiritueller Praxis.","Konflikte solange vertagen, bis alle Aufgaben erledigt sind.","Die Delegation sämtlicher organisatorischer Aufgaben an den Partner."],"explanation":"Ein spiritueller Fokus ersetzt keine gerechte Organisation von Alltagsarbeit.","source":"Deida (1997), Kapitel 14, Buchseite 23."},{"id":"book81-ch15","chapterNo":15,"page":25,"chapter":"Kapitel 15 · Herausforderungen in der Beziehung","topic":"Herausforderungen in der Beziehung","track":"theory","question":"Wie deutet Deida wiederkehrende Herausforderungen durch die Partnerin?","answers":["Als mögliche Prüfung von Präsenz und innerer Ausrichtung des Mannes.","Als Beweis, dass jede konkrete Kritik inhaltlich bedeutungslos ist.","Als Zeichen dafür, dass die Frau absichtlich schaden möchte.","Als diagnostisch zuverlässigen Ausdruck femininer Essenz."],"explanation":"Dies ist eine spekulative Deutung des Autors; konkrete Anliegen müssen zuerst ernst genommen werden.","source":"Deida (1997), Kapitel 15, Buchseite 25."},{"id":"book81-ch16","chapterNo":16,"page":29,"chapter":"Kapitel 16 · Worte und wechselnde Gefühle","topic":"Worte und wechselnde Gefühle","track":"theory","question":"Wie erklärt Deida scheinbar widersprüchliche Aussagen in emotionalen Situationen?","answers":["Gefühle und aktuelle Beziehungserfahrung können nach seiner Darstellung sprachliche Aussagen verändern.","Widersprüche zeigen, dass Frauen rechtlich nicht verantwortlich sind.","Jede konkrete Zusage ist im femininen Modus automatisch unwirksam.","Eine emotionale Aussage muss nie in ihrem Inhalt geprüft werden."],"explanation":"Das Buch verallgemeinert stark; tatsächliche Vereinbarungen bleiben verbindlich und überprüfbar.","source":"Deida (1997), Kapitel 16, Buchseite 29."},{"id":"book81-ch17","chapterNo":17,"page":31,"chapter":"Kapitel 17 · Anerkennung und Lob","topic":"Anerkennung und Lob","track":"theory","question":"Welche unterschiedliche Wachstumsdynamik behauptet Deida?","answers":["Maskuline Energie reagiere eher auf Herausforderung, feminine eher auf Wertschätzung.","Männer seien grundsätzlich nicht empfänglich für Anerkennung.","Frauen könnten keine anspruchsvolle Rückmeldung aufnehmen.","Lob müsse an die Stelle jeder konkreten Kommunikation treten."],"explanation":"Diese geschlechtsbezogene Typisierung ist Deidas These, keine starre psychologische Regel.","source":"Deida (1997), Kapitel 17, Buchseite 31."},{"id":"book81-ch18","chapterNo":18,"page":32,"chapter":"Kapitel 18 · Duldung und Groll","topic":"Duldung und Groll","track":"theory","question":"Was kritisiert Deida an stillschweigendem Erdulden ungelöster Beziehungsspannungen?","answers":["Unausgesprochene Distanz könne sich zu Ressentiment entwickeln.","Akzeptanz sei in jeder Situation schädlich.","Jede Spannung müsse unmittelbar körperlich aufgelöst werden.","Groll entstehe ausschließlich durch einseitige emotionale Schwäche."],"explanation":"Beziehungsprobleme brauchen differenzierte Bearbeitung statt reiner Duldung oder dominierender Kontrolle.","source":"Deida (1997), Kapitel 18, Buchseite 32."},{"id":"book81-ch19","chapterNo":19,"page":34,"chapter":"Kapitel 19 · Emotion nicht zeranalysieren","topic":"Emotion nicht zeranalysieren","track":"theory","question":"Welche Alternative stellt Deida einem rein analytischen Zugriff auf emotionale Stimmungen gegenüber?","answers":["Gegenwärtige Präsenz und Verbindung statt jeder Regung eine eindeutige Ursache zuzuschreiben.","Die Gefühle des Gegenübers grundsätzlich ignorieren.","Konkrete Fragen nach Ursachen grundsätzlich verbieten.","Aus jeder Stimmung eine feste Charaktereigenschaft ableiten."],"explanation":"Eine Atmosphäre wahrnehmen ist hilfreich; Analyse ist nicht generell wertlos.","source":"Deida (1997), Kapitel 19, Buchseite 34."},{"id":"book81-ch20","chapterNo":20,"page":36,"chapter":"Kapitel 20 · Emotionale Probleme „reparieren“","topic":"Emotionale Probleme „reparieren“","track":"theory","question":"Was lehnt Deida im Umgang mit starken Gefühlen der Partnerin besonders ab?","answers":["Sie wie ein isoliertes technisches Problem behandeln, das die Partnerin allein lösen müsse.","Das Recht einer Person, eigene Gefühle selbst zu regulieren.","Jede Form gegenseitiger emotionaler Unterstützung.","Die Möglichkeit, Veränderungen gemeinsam zu besprechen."],"explanation":"Die Zuschreibung einer ausschließlich weiblichen Gefühlsnatur ist kritisch einzuordnen.","source":"Deida (1997), Kapitel 20, Buchseite 36."},{"id":"book81-ch21","chapterNo":21,"page":38,"chapter":"Kapitel 21 · Bei Intensität präsent bleiben","topic":"Bei Intensität präsent bleiben","track":"theory","question":"Was enthält Deidas Empfehlung, der Intensität „bis zu einem Punkt“ zu begegnen?","answers":["Zugewandt und standhaft bleiben, aber die eigenen Grenzen nicht vollständig verlieren.","Jede Eskalation unbegrenzt ertragen und nie Abstand nehmen.","Lautstärke stets durch noch größere Lautstärke übertreffen.","Das Gegenüber ohne Zustimmung körperlich beruhigen."],"explanation":"Der Punkt der Grenze ist wichtig; Angst, Bedrohung und Gewalt verlangen Sicherheit statt Polaritätsarbeit.","source":"Deida (1997), Kapitel 21, Buchseite 38."},{"id":"book81-ch22","chapterNo":22,"page":40,"chapter":"Kapitel 22 · Entscheidungen und Verantwortung","topic":"Entscheidungen und Verantwortung","track":"theory","question":"Wie beschreibt Deida den „maskulinen Beitrag“ zur Entscheidungsfindung?","answers":["Richtung anbieten und Verantwortung für die eigene Entscheidung tragen.","Der Partnerin grundsätzlich ihre Entscheidungskompetenz absprechen.","Bei Unsicherheit automatisch die Kontrolle übernehmen.","Unterschiedliche Wünsche ohne Rücksprache vereinheitlichen."],"explanation":"Eine Initiative ist nur hilfreich, wenn Wahlfreiheit und Mitbestimmung gewahrt bleiben.","source":"Deida (1997), Kapitel 22, Buchseite 40."},{"id":"book81-ch23","chapterNo":23,"page":44,"chapter":"Kapitel 23 · Anziehung zum Femininen","topic":"Anziehung zum Femininen","track":"theory","question":"Was bezeichnet Deida als Anziehung zum Femininen?","answers":["Eine umfassende Resonanz auf Lebendigkeit und Ausstrahlung, nicht nur auf eine bestimmte Person.","Eine ausschließlich biologische Reaktion auf feste weibliche Merkmale.","Den eindeutigen Nachweis einer ungesunden Beziehung.","Eine moralische Verpflichtung, jedem Attraktionsimpuls zu folgen."],"explanation":"Die Energiebeschreibung ist spirituell-metaphorisch, keine objektive Messgröße.","source":"Deida (1997), Kapitel 23, Buchseite 44."},{"id":"book81-ch24","chapterNo":24,"page":46,"chapter":"Kapitel 24 · Komplementäre Polarität","topic":"Komplementäre Polarität","track":"theory","question":"Welche Beziehung zwischen sexueller Essenz und Partnerwahl behauptet Deida?","answers":["Ausgeprägt maskuline Essenz könne sich besonders zu ausgeprägt femininer Essenz hingezogen fühlen.","Gleiche Eigenschaften schließen Liebesbeziehungen grundsätzlich aus.","Die Pole müssen immer dieselben Geschlechter haben.","Unterschiede in Interessen reichen immer für sexuelle Spannung."],"explanation":"Deidas Komplementarität ist ein Modell, keine universelle Partnerwahlregel.","source":"Deida (1997), Kapitel 24, Buchseite 46."},{"id":"book81-ch25","chapterNo":25,"page":50,"chapter":"Kapitel 25 · Wichtige Qualitäten beim Gegenüber","topic":"Wichtige Qualitäten beim Gegenüber","track":"theory","question":"Welche Unterscheidung macht Deida zwischen praktischer Partnerschaft und polarer Anziehung?","answers":["Alltagstaugliche Eigenschaften und erotische Ausstrahlung seien verschiedene Bewertungsdimensionen.","Organisatorische Verlässlichkeit beweise die Stärke des erotischen Pols.","Eine kompetente Partnerin könne keine erotische Ausstrahlung haben.","Lust sei ausschließlich durch gemeinsame berufliche Ziele bestimmt."],"explanation":"Beide Qualitäten können wichtig sein; individuelle Prioritäten sind nicht vorgeschrieben.","source":"Deida (1997), Kapitel 25, Buchseite 50."},{"id":"book81-ch26","chapterNo":26,"page":52,"chapter":"Kapitel 26 · Begehren nach Vielfalt","topic":"Begehren nach Vielfalt","track":"theory","question":"Welche These formuliert Deida zu sexueller Vielfalt bei maskuliner Essenz?","answers":["Auch in Bindungen könne Anziehung zu anderen Menschen fortbestehen.","Ein sexuelles Interesse begründe automatisch die Erlaubnis zu handeln.","Bindung und sexuelle Wünsche seien grundsätzlich unvereinbar.","Alle maskulinen Personen müssten nichtmonogam leben."],"explanation":"Zwischen Impuls, Vereinbarung, Entscheidung und Handlung muss unterschieden werden.","source":"Deida (1997), Kapitel 26, Buchseite 52."},{"id":"book81-ch27","chapterNo":27,"page":54,"chapter":"Kapitel 27 · Jugend und Energie","topic":"Jugend und Energie","track":"theory","question":"Wie wertet Deida in diesem Kapitel die Wirkung jugendlicher Ausstrahlung?","answers":["Er beschreibt Jugend als eine mögliche Quelle besonders lebendig empfundener femininer Energie.","Er behauptet, Alter habe nie Einfluss auf Anziehung.","Er fordert eine verbindliche Partnerwahl nach jungem Alter.","Er widerlegt jedes erotische Interesse an reifen Frauen."],"explanation":"Die pauschalen Alterszuschreibungen sind normativ und potenziell diskriminierend.","source":"Deida (1997), Kapitel 27, Buchseite 54."},{"id":"book81-ch28","chapterNo":28,"page":56,"chapter":"Kapitel 28 · Temperatur-Metapher","topic":"Temperatur-Metapher","track":"theory","question":"Was versteht Deida mit der „Temperatur“ einer Frau?","answers":["Eine metaphorische Beschreibung der subjektiv erlebten Wirkung von Ausstrahlung.","Einen objektiv messbaren physiologischen Wärmegrad.","Eine wissenschaftliche Klassifikation nach Haar- und Hautfarbe.","Eine feste Diagnose des emotionalen Charakters."],"explanation":"Das Kapitel enthält ethnisierende Typisierungen, die ausdrücklich keine wissenschaftliche Grundlage für Beurteilungen sind.","source":"Deida (1997), Kapitel 28, Buchseite 56."},{"id":"book81-ch29","chapterNo":29,"page":60,"chapter":"Kapitel 29 · Gegenseitige Wahl","topic":"Gegenseitige Wahl","track":"theory","question":"Was betont Deida mit „Choose a Woman Who Chooses You“?","answers":["Eine Beziehung braucht erkennbares beidseitiges Wollen statt einseitiger Überzeugungsarbeit.","Hartnäckigkeit könne fehlende Zustimmung ersetzen.","Vermeintliches Zögern müsse stets als versteckte Einwilligung gelten.","Eine Ablehnung sei vor allem eine Herausforderung männlicher Stärke."],"explanation":"Ein Nein respektieren und Interesse nicht hineininterpretieren.","source":"Deida (1997), Kapitel 29, Buchseite 60."},{"id":"book81-ch30","chapterNo":30,"page":61,"chapter":"Kapitel 30 · Wortlaut und vermeintlicher Test","topic":"Wortlaut und vermeintlicher Test","track":"theory","question":"Welche Deutung schlägt Deida bei manchen Bitten der Partnerin vor?","answers":["Hinter dem Wortlaut könne aus seiner Sicht auch ein Test der männlichen Klarheit stehen.","Jede konkrete Bitte meine garantiert das Gegenteil.","Wünsche seien in emotionalen Momenten bedeutungslos.","Eine Partnerin habe grundsätzlich kein Recht auf klare Auskunft."],"explanation":"Solche Testdeutungen sind spekulativ; erst nach dem tatsächlichen Anliegen fragen.","source":"Deida (1997), Kapitel 30, Buchseite 61."},{"id":"book81-ch31","chapterNo":31,"page":63,"chapter":"Kapitel 31 · Beschwerden als Signal","topic":"Beschwerden als Signal","track":"theory","question":"Wie interpretiert Deida die Beschwerde einer Partnerin?","answers":["Mitunter als Ruf nach Präsenz und Ausrichtung, nicht allein nach einer Sachlösung.","Jede Beschwerde belege manipulative Absicht.","Der materielle Inhalt sei niemals überprüfungswürdig.","Ein Konflikt könne durch sexuelle Spannung zuverlässig gelöst werden."],"explanation":"Die Deutung darf berechtigte Sachkritik wie ungleiche Hausarbeit nicht überdecken.","source":"Deida (1997), Kapitel 31, Buchseite 63."},{"id":"book81-ch32","chapterNo":32,"page":66,"chapter":"Kapitel 32 · Prioritäten und Begehren","topic":"Prioritäten und Begehren","track":"theory","question":"Welches Spannungsverhältnis behauptet Deida beim Wunsch, „Nummer eins“ zu sein?","answers":["Eine Partnerin könne zugleich Nähe wünschen und eine eigenständig ausgerichtete Person attraktiv finden.","Eine Partnerin wolle tatsächlich nie verbindliche Zuwendung.","Eine Lebensmission schließe gemeinsame Entscheidungen zwingend aus.","Nur emotionale Distanz erzeuge dauerhaft sichere Bindung."],"explanation":"Doppelte Bedürfnisse sind möglich; daraus folgt kein Geschlechtergesetz.","source":"Deida (1997), Kapitel 32, Buchseite 66."},{"id":"book81-ch33","chapterNo":33,"page":68,"chapter":"Kapitel 33 · Vergangenheit und aktueller Moment","topic":"Vergangenheit und aktueller Moment","track":"theory","question":"Was behauptet Deida über die Reaktion auf eine momentane Verletzung?","answers":["Im aktuellen Beziehungserleben könne eine einzelne Verletzung schwerer wiegen als frühere Verdienste.","Frühere Reparaturversuche seien deshalb grundsätzlich unwichtig.","Ein einmaliger Fehler lösche objektiv alle gelingenden Jahre.","Eine Partnerperson könne keine differenzierte Erinnerung haben."],"explanation":"Bedeutsamkeit des Moments darf nicht zur Abwertung der gesamten Beziehungsgeschichte führen.","source":"Deida (1997), Kapitel 33, Buchseite 68."},{"id":"book81-ch34","chapterNo":34,"page":70,"chapter":"Kapitel 34 · Richtung anbieten","topic":"Richtung anbieten","track":"theory","question":"Was bezeichnet Deida als erotisch bedeutsame Demonstration von Richtung?","answers":["Präsente Initiative, auf die sich die Partnerin freiwillig verlassen kann.","Entscheidungsgewalt ohne Einverständnis.","Ständige Kontrolle über finanzielle und sexuelle Entscheidungen.","Das Verbergen eigener Unsicherheit gegenüber der Partnerin."],"explanation":"Initiative braucht Einvernehmen; Nähe darf nicht als Unterordnung erzwungen werden.","source":"Deida (1997), Kapitel 34, Buchseite 70."},{"id":"book81-ch35","chapterNo":35,"page":74,"chapter":"Kapitel 35 · Freiheit und männliche Essenz","topic":"Freiheit und männliche Essenz","track":"theory","question":"Wie beschreibt Deida den Drang nach Freiheit bei maskuliner Essenz?","answers":["Als Streben nach dem Erleben von Befreiung aus Begrenzungen.","Als Ablehnung aller verbindlichen Beziehungen.","Als Pflicht, emotionale Abhängigkeiten zu leugnen.","Als medizinisch begründetes Grundbedürfnis ausschließlich von Männern."],"explanation":"Sein Begriff von Freiheit ist existenziell und wertbezogen, keine klinische Geschlechtsdiagnose.","source":"Deida (1997), Kapitel 35, Buchseite 74."},{"id":"book81-ch36","chapterNo":36,"page":76,"chapter":"Kapitel 36 · Dunkle Wünsche wahrnehmen","topic":"Dunkle Wünsche wahrnehmen","track":"theory","question":"Was verlangt Deida beim Umgang mit schwer eingestandenen erotischen Impulsen?","answers":["Die eigenen Impulse bewusst anerkennen, statt sie durch Verdrängung aus dem Blick zu verlieren.","Sie ungefragt in die Tat umsetzen.","Sie als Beweis für einen verborgenen Charakterdefekt interpretieren.","Sie der Partnerperson als verpflichtende Aufgabe übertragen."],"explanation":"Wahrnehmen, verantworten und handeln sind unterschiedliche Ebenen.","source":"Deida (1997), Kapitel 36, Buchseite 76."},{"id":"book81-ch37","chapterNo":37,"page":79,"chapter":"Kapitel 37 · „Killer“-Metapher","topic":"„Killer“-Metapher","track":"theory","question":"Wofür steht Deidas provokatives Bild des „Killers“ im Mann?","answers":["Für eine nicht zurückweichende Entschlossenheit und Handlungsfähigkeit.","Für eine wörtliche Aufforderung zu Aggression gegen die Partnerin.","Für die Überzeugung, Angst sei biologisch unmännlich.","Für ein Recht auf körperliche Grenzverletzung."],"explanation":"Gewaltmetaphorik ist problematisch; therapeutisch darf sie niemals Gewalt legitimieren.","source":"Deida (1997), Kapitel 37, Buchseite 79."},{"id":"book81-ch38","chapterNo":38,"page":81,"chapter":"Kapitel 38 · Bewusstsein und Intensität","topic":"Bewusstsein und Intensität","track":"theory","question":"Was fordert Deida, wenn die emotionale Energie des Gegenübers stark ansteigt?","answers":["Präsenz und Selbstkontakt bewahren, statt sich reflexhaft zu verschließen.","Jede Eskalation als erotisches Signal deuten.","Die andere Person körperlich überwältigen, damit sie sich öffnet.","Die gesamte Stimmungsregulation des Gegenübers übernehmen."],"explanation":"Bei Streit und Gefahr gilt Deeskalation, Sicherheit und Einwilligung vor symbolischer Polarität.","source":"Deida (1997), Kapitel 38, Buchseite 81."},{"id":"book81-ch39","chapterNo":39,"page":84,"chapter":"Kapitel 39 · Feminine Fülle","topic":"Feminine Fülle","track":"theory","question":"Was meint Deida mit „Feminine Is Abundant“?","answers":["Er erlebt die Welt metaphorisch als reich an lebendiger femininer Energie.","Alle Frauen seien jederzeit erotisch verfügbar.","Es gebe nachweislich keine Einsamkeit.","Jede Person müsse ihre Gefühle mit weiblicher Energie erklären."],"explanation":"Eine spirituelle Füllemetapher ist keine Aussage über tatsächliche Verfügbarkeit von Menschen.","source":"Deida (1997), Kapitel 39, Buchseite 84."},{"id":"book81-ch40","chapterNo":40,"page":85,"chapter":"Kapitel 40 · Ausstrahlung im Alter","topic":"Ausstrahlung im Alter","track":"theory","question":"Worauf lenkt Deida im Kapitel über ältere Frauen die Aufmerksamkeit?","answers":["Auf Tiefe, Ausstrahlung und Reife jenseits jugendlicher Erscheinung.","Auf die Pflicht, Attraktion ausschließlich altersabhängig zu bewerten.","Auf die These, ältere Frauen hätten keine Sexualität.","Auf die Unvereinbarkeit von Alter und sinnlicher Lebendigkeit."],"explanation":"Der Text wertschätzt Reife, enthält aber auch eigene generalisierende Schönheitsannahmen.","source":"Deida (1997), Kapitel 40, Buchseite 85."},{"id":"book81-ch41","chapterNo":41,"page":87,"chapter":"Kapitel 41 · Begehren in Kreativität wenden","topic":"Begehren in Kreativität wenden","track":"theory","question":"Was bedeutet bei Deida, Lust „in Gaben zu verwandeln“?","answers":["Erregung als subjektive Inspiration für kreative und zugewandte Handlungen nutzen.","Einen sexuellen Impuls grundsätzlich gegenüber anderen ausleben.","Energieumwandlung als medizinisch bewiesenes Verfahren verstehen.","Erotische Fantasie aus Prinzip als moralisch falsch behandeln."],"explanation":"Der Autor beschreibt eine spirituelle Praxis, keine gesicherte Behandlungsmethode.","source":"Deida (1997), Kapitel 41, Buchseite 87."},{"id":"book81-ch42","chapterNo":42,"page":89,"chapter":"Kapitel 42 · Unterdrücktes Begehren","topic":"Unterdrücktes Begehren","track":"theory","question":"Was verbindet Deida mit „depolarisiertem“ Begehren?","answers":["Das Erleben, den eigenen Zugang zu Lebendigkeit und erotischer Resonanz zu verlieren.","Die Tatsache, in einer Beziehung vorübergehend keinen Sex zu wollen.","Eine medizinische Diagnose mit eindeutigen Grenzwerten.","Eine Aufforderung, eine Beziehung für Abwechslung zu verlassen."],"explanation":"Niedrige Lust kann zahlreiche Gründe haben und ist nicht automatisch „Depolarisierung“.","source":"Deida (1997), Kapitel 42, Buchseite 89."},{"id":"book81-ch43","chapterNo":43,"page":92,"chapter":"Kapitel 43 · Anziehung als Inspiration","topic":"Anziehung als Inspiration","track":"theory","question":"Wie kann Attraktion nach Deida über das unmittelbare Gegenüber hinausweisen?","answers":["Sie kann als Impuls verstanden werden, die eigene Präsenz und Lebensgestaltung zu vertiefen.","Die begehrte Person muss verfügbar werden, damit Wachstum möglich ist.","Die eigene Lebensmission soll vollständig von Attraktion bestimmt werden.","Äußerliche Schönheit ist der einzige Zugang zu innerer Entwicklung."],"explanation":"Das Bild ist spirituell; andere Menschen bleiben Subjekte mit eigenen Grenzen.","source":"Deida (1997), Kapitel 43, Buchseite 92."},{"id":"book81-ch44","chapterNo":44,"page":96,"chapter":"Kapitel 44 · Ejakulation bewusst gestalten","topic":"Ejakulation bewusst gestalten","track":"theory","question":"Was ist Deidas zentrale These zur Ejakulation?","answers":["Er regt bewussten Umgang mit Orgasmus und Ejakulation als Teil seiner sexuellen Praxis an.","Ejakulation sei grundsätzlich medizinisch schädlich.","Jede Person müsse Ejakulation vermeiden, um gesund zu bleiben.","Kontrolle über Ejakulation garantiere eine erfüllte Beziehung."],"explanation":"Körperliche und energetische Behauptungen sind nicht automatisch evidenzbasierte Gesundheitsratschläge.","source":"Deida (1997), Kapitel 44, Buchseite 96."},{"id":"book81-ch45","chapterNo":45,"page":100,"chapter":"Kapitel 45 · Atem und körperliche Öffnung","topic":"Atem und körperliche Öffnung","track":"theory","question":"Wie beschreibt Deida das Atmen entlang der Vorderseite des Körpers?","answers":["Als körperlich-spirituelle Praxis, Offenheit und Präsenz zu erleben.","Als standardisiertes medizinisches Atemtestverfahren.","Als Ersatz für Gespräch und psychologische Abklärung.","Als Technik, die unabhängig von Beschwerden immer nötig sei."],"explanation":"Die Übung ist seine spirituelle Körperpraxis; Beschwerden oder Überforderung sind ernst zu nehmen.","source":"Deida (1997), Kapitel 45, Buchseite 100."},{"id":"book81-ch46","chapterNo":46,"page":103,"chapter":"Kapitel 46 · Energie entlang der Wirbelsäule","topic":"Energie entlang der Wirbelsäule","track":"theory","question":"Wie ist Deidas Darstellung des Orgasmus entlang der Wirbelsäule einzuordnen?","answers":["Als sexual-spirituelle Beschreibung subjektiver Erfahrung.","Als anatomisch nachgewiesener Verlauf von Samenflüssigkeit.","Als medizinischer Beweis für höhere Leistungsfähigkeit.","Als für alle Menschen sichere und zwingende Methode."],"explanation":"Keine Übernahme körperlicher Energiebehauptungen als gesicherte Physiologie.","source":"Deida (1997), Kapitel 46, Buchseite 103."},{"id":"book81-ch47","chapterNo":47,"page":108,"chapter":"Kapitel 47 · Primäre Asymmetrie","topic":"Primäre Asymmetrie","track":"theory","question":"Welche Asymmetrie behauptet Deida zwischen maskuliner und femininer Essenz?","answers":["Eine stärkere Priorität von Mission einerseits und Beziehung andererseits.","Eine universelle biologische Pflichtverteilung aller Geschlechter.","Dass Männer keine Bindung wünschen und Frauen keine Lebensziele haben.","Dass gemeinsame Entscheidungen grundsätzlich schaden."],"explanation":"Dies ist eine wertende Typologie und keine empirisch gesicherte Regel über Männer und Frauen.","source":"Deida (1997), Kapitel 47, Buchseite 108."},{"id":"book81-ch48","chapterNo":48,"page":111,"chapter":"Kapitel 48 · Verantwortung für Intimitätswachstum","topic":"Verantwortung für Intimitätswachstum","track":"theory","question":"Wie verteilt Deida im Modell die Verantwortung für Entwicklung und Energie der Intimität?","answers":["Er ordnet Richtung und Wachstum eher dem maskulinen, Vitalität eher dem femininen Pol zu.","Er fordert, dass nur ein Partner für jedes Problem verantwortlich sei.","Er hält beide Pole für identisch und austauschbar in ihren Pflichten.","Er sieht Intimität ausschließlich als private Angelegenheit ohne Aushandlung."],"explanation":"Das ist seine spirituelle Rollenmetapher; in Beratung bleibt Verantwortung beider Personen wichtig.","source":"Deida (1997), Kapitel 48, Buchseite 111."},{"id":"book81-ch49","chapterNo":49,"page":114,"chapter":"Kapitel 49 · Praxis und Wachstum","topic":"Praxis und Wachstum","track":"theory","question":"Worauf richtet Deida die Forderung nach regelmäßiger Praxis in Beziehungen?","answers":["Auf kontinuierliche bewusste Entwicklung statt mechanischem Weiterfunktionieren.","Auf eine Pflicht zu ständig wachsender sexueller Aktivität.","Auf Überlegenheit einer Person bei jeder Entscheidung.","Auf die Überwachung des persönlichen Fortschritts der Partnerin."],"explanation":"Wachstum verlangt Gegenseitigkeit und Freiwilligkeit statt Optimierungsdruck.","source":"Deida (1997), Kapitel 49, Buchseite 114."},{"id":"book81-ch50","chapterNo":50,"page":116,"chapter":"Kapitel 50 · Alleinsein und Austausch","topic":"Alleinsein und Austausch","track":"theory","question":"Welche Funktion gibt Deida Zeiten allein und im Austausch mit anderen Männern?","answers":["Die eigene Lebensausrichtung erneuern und sich ehrlich spiegeln lassen.","Beziehungen grundsätzlich verlassen, um unabhängig zu werden.","Entscheidungen nur noch im Männerkreis treffen.","Kritik der Partnerin durch Freunde ersetzen."],"explanation":"Auch andere Gemeinschaften und Einzelwege können diese Funktion erfüllen.","source":"Deida (1997), Kapitel 50, Buchseite 116."},{"id":"book81-ch51","chapterNo":51,"page":119,"chapter":"Kapitel 51 · Sich im Leben auflösen","topic":"Sich im Leben auflösen","track":"theory","question":"Was beschreibt Deida mit „Practice Dissolving“?","answers":["Sich immer wieder für Offenheit und Hingabe im gegenwärtigen Leben üben.","Die eigene Selbstbestimmung vollständig aufgeben.","Mit jeder emotionalen Intensität einverstanden sein müssen.","Sich in gefährlichen Situationen absichtlich entgrenzen."],"explanation":"Seine spirituelle Sprache über Auflösung ist kein Auftrag zur Selbstgefährdung.","source":"Deida (1997), Kapitel 51, Buchseite 119."},{"id":"book81-t01","chapterNo":15,"chapter":"Kapitel 15 · Beratungstransfer","topic":"Sachkritik als vermeintlicher Test","track":"transfer","page":25,"question":"Eine Partnerin sagt: „Ich erledige jeden Abend die Küche allein.“ Welche erste Reaktion vermeidet einen Deutungsfehler?","answers":["Die konkreten Absprachen und Belastungen beider erfragen.","Die Aussage sofort als Test männlicher Präsenz klassifizieren.","Mehr erotische Initiative empfehlen, ehe der Haushalt geklärt ist.","Der Partnerin erklären, dass Beschwerden laut Deida oft keinen Inhalt hätten."],"explanation":"Eine Polaritätsdeutung darf überprüfbare Alltagsungerechtigkeit nicht verdecken.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 15; keine Originalaussage."},{"id":"book81-t02","chapterNo":16,"chapter":"Kapitel 16 · Beratungstransfer","topic":"Widersprüchliche Aussagen","track":"transfer","page":29,"question":"Nach einem Streit sagt eine Person „Ich will nie wieder mit dir reden“, später sucht sie Kontakt. Wie gehst du mit Deidas Modell um?","answers":["Emotionale Lage und tatsächliche aktuelle Wünsche klären, ohne eine ganze Geschlechtsgruppe daraus abzuleiten.","Die ursprüngliche Aussage grundsätzlich als Lüge bewerten.","Jede Aussage von Frauen in Konflikten prinzipiell entwerten.","Die neue Annäherung als stillschweigende Zustimmung zu allem sehen."],"explanation":"Beziehungsdynamik ist nicht dasselbe wie fehlende Verantwortung für Aussagen.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 16; keine Originalaussage."},{"id":"book81-t03","chapterNo":17,"chapter":"Kapitel 17 · Beratungstransfer","topic":"Lob und Kritik","track":"transfer","page":31,"question":"Eine Frau bittet ausdrücklich um ehrliches kritisches Feedback. Was folgt aus Deidas Lobthese?","answers":["Ihre konkrete Bitte ernst nehmen und Feedback respektvoll anbieten.","Nur loben, weil Kritik feminine Entwicklung prinzipiell verhindert.","Eine männliche Person um Erlaubnis zur Kritik bitten.","Die Bitte als versteckten Test abtun."],"explanation":"Individuelle Kommunikation hat Vorrang vor Typisierung.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 17; keine Originalaussage."},{"id":"book81-t04","chapterNo":21,"chapter":"Kapitel 21 · Beratungstransfer","topic":"Intensive Emotionen und Sicherheit","track":"transfer","page":38,"question":"Eine Person schreit und wirft ein Glas. Welche Priorität gilt?","answers":["Zuerst unmittelbare Sicherheit und Deeskalation klären; körperliche Annäherung nicht erzwingen.","Die Intensität als Einladung zum erotischen Spiel auffassen.","Beide auffordern, so lange in der Szene zu bleiben, bis sich Polarität aufbaut.","Die lautere Person umarmen, um ihre Energie zu verwandeln."],"explanation":"Deidas Bild von Präsenz darf Gewalt und Bedrohung nicht romantisieren.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 21; keine Originalaussage."},{"id":"book81-t05","chapterNo":22,"chapter":"Kapitel 22 · Beratungstransfer","topic":"Richtung und Einverständnis","track":"transfer","page":40,"question":"Ein Partner möchte den Abend gestalten, die andere Person zögert. Was ist eine passende Initiative?","answers":["Ein konkretes Angebot machen und echte Wahlfreiheit lassen.","Die Entscheidung ohne Rückfrage treffen, um Führung zu beweisen.","Zögern als unterschwellige Zustimmung behandeln.","Von einer weiblichen Person verlangen, sich führen zu lassen."],"explanation":"Führung ohne Freiwilligkeit wird zur Kontrolle.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 22; keine Originalaussage."},{"id":"book81-t06","chapterNo":24,"chapter":"Kapitel 24 · Beratungstransfer","topic":"Gegensätze oder Kompatibilität","track":"transfer","page":46,"question":"Ein gleichgeschlechtliches Paar vermisst Spannung. Was kannst du aus Deida verantwortbar nutzen?","answers":["Nach gewünschter Dynamik und erlebten Unterschieden fragen, ohne feste Geschlechterrollen anzunehmen.","Eine Person dauerhaft zum maskulinen Pol bestimmen.","Beiden sagen, das Modell sei nur für heterosexuelle Beziehungen gültig.","Gegensätzlichkeit als einzige Ursache jeder Lustveränderung setzen."],"explanation":"Deida diskutiert Polarität ausdrücklich jenseits biologischer Geschlechter.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 24; keine Originalaussage."},{"id":"book81-t07","chapterNo":26,"chapter":"Kapitel 26 · Beratungstransfer","topic":"Anziehung zu anderen","track":"transfer","page":52,"question":"Eine Person erzählt von Anziehung zu einer dritten Person in einer monogamen Beziehung. Was klärst du?","answers":["Das Erleben, die bestehenden Vereinbarungen und gewünschte nächste Schritte unterscheiden.","Die Anziehung sofort als Anspruch auf Öffnung der Beziehung werten.","Die Attraktion ausnahmslos als Ende der Liebe deuten.","Dem Partner ungefragt eine Änderung der Vereinbarung mitteilen."],"explanation":"Empfindung ist nicht Zustimmung zu einer Handlung.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 26; keine Originalaussage."},{"id":"book81-t08","chapterNo":27,"chapter":"Kapitel 27 · Beratungstransfer","topic":"Altersbilder","track":"transfer","page":54,"question":"Eine ältere Klientin befürchtet, aufgrund ihres Alters unerotisch zu sein. Wie vermeidest du Altersstereotype?","answers":["Ihre Erfahrung und Selbstbilder erkunden, ohne Attraktivität aus dem Alter abzuleiten.","Das Kapitel über Jugend als Beleg ihrer Befürchtung anbieten.","Ihr sagen, dass altersbedingte Attraktivität objektiv messbar sei.","Die Sorge ausschließlich auf ihren Körper reduzieren."],"explanation":"Deidas unterschiedliche Bilder von Jugend und Reife sind keine individuelle Diagnose.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 27; keine Originalaussage."},{"id":"book81-t09","chapterNo":28,"chapter":"Kapitel 28 · Beratungstransfer","topic":"Ethnische Temperaturzuschreibungen","track":"transfer","page":56,"question":"In Deidas Temperaturkapitel werden Hautfarbe und Herkunft zur Beschreibung sexueller Energie benutzt. Wie gehst du damit um?","answers":["Die ethnisierenden Zuschreibungen als unbegründet zurückweisen und auf das konkrete Erleben fokussieren.","Die Einteilung in ein Assessment der Klientin aufnehmen.","Den Hauttyp als Ersatz für Fragen nach Vorlieben verwenden.","Die Kategorien durch Tests zur emotionalen Stabilität bestätigen."],"explanation":"Keine Übernahme stereotyper Herkunftsbilder in Beratung oder Diagnose.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 28; keine Originalaussage."},{"id":"book81-t10","chapterNo":29,"chapter":"Kapitel 29 · Beratungstransfer","topic":"Nicht erwidertes Interesse","track":"transfer","page":60,"question":"Ein Mann interpretiert wiederholte Ablehnung als versteckten „Test“. Welche Intervention ist verantwortbar?","answers":["Die Ablehnung respektieren und zwischen Hoffnung und beobachteter Zustimmung unterscheiden.","Zu mehr Beharrlichkeit raten, um Richtung zu beweisen.","Die Partnerperson auf ungeäußerte Wünsche festlegen.","Die Ablehnung als Chance zur stärkeren erotischen Führung verstehen."],"explanation":"Erkennbare Wahlfreiheit und gegenseitiges Interesse gehen vor.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 29; keine Originalaussage."},{"id":"book81-t11","chapterNo":30,"chapter":"Kapitel 30 · Beratungstransfer","topic":"Hinter dem Wunsch ein Test?","track":"transfer","page":61,"question":"Eine Partnerin bittet um pünktliche Abholung und wirkt angespannt. Was ist zuerst zu tun?","answers":["Die Bitte praktisch ernst nehmen und bei Unklarheit nachfragen.","Ihre Bitte absichtlich ignorieren, um männliche Eigenständigkeit zu zeigen.","Pünktlichkeit als irrelevanten Inhalt eines femininen Tests klassifizieren.","Jede Bitte grundsätzlich nach ihrer verborgenen Bedeutung umkehren."],"explanation":"Eine spekulative Testhypothese ersetzt keine verständliche Bitte.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 30; keine Originalaussage."},{"id":"book81-t12","chapterNo":31,"chapter":"Kapitel 31 · Beratungstransfer","topic":"Kritik an Care-Arbeit","track":"transfer","page":63,"question":"Eine Person kritisiert fehlende Beteiligung an Kinderbetreuung. Welche Antwort passt?","answers":["Die Aufgabenverteilung und die dahinterliegenden Gefühle getrennt untersuchen.","Den Sachinhalt ignorieren, weil Beschwerden angeblich „content-free“ sind.","Polarität nur durch mehr sexuelle Führung wiederherstellen.","Die Aufgabe als Beweis mangelnder Hingabe der anderen Person auslegen."],"explanation":"Materielle Gerechtigkeit ist ein eigenständiger Teil von Beziehungszufriedenheit.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 31; keine Originalaussage."},{"id":"book81-t13","chapterNo":32,"chapter":"Kapitel 32 · Beratungstransfer","topic":"Richtung und Paarentscheidung","track":"transfer","page":66,"question":"Ein Paar diskutiert den Umzug in eine andere Stadt. Einer hat klare Ziele, die andere fühlt sich übergangen. Was wäre hilfreich?","answers":["Individuelle Ziele und Mitbestimmung auf Augenhöhe klären.","Die persönliche Mission automatisch über gemeinsame Folgen stellen.","Die Partnerperson um Dankbarkeit für Führung bitten.","Den Widerspruch als Mangel an femininer Offenheit deuten."],"explanation":"Autonomie ist mit Verbindlichkeit und gemeinsamem Entscheiden zu verbinden.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 32; keine Originalaussage."},{"id":"book81-t14","chapterNo":33,"chapter":"Kapitel 33 · Beratungstransfer","topic":"Verletzung trotz guter Vergangenheit","track":"transfer","page":68,"question":"Ein Partner zählt zehn Jahre guter Leistungen auf, nachdem er heute gekränkt hat. Wie lässt sich beides würdigen?","answers":["Die aktuelle Verletzung anerkennen und zugleich die langfristige Beziehung nicht ausblenden.","Vergangene Leistungen als Freibrief gegen Kritik behandeln.","Einen Moment zum Beweis erklären, dass alle Jahre schlecht waren.","Die Verletzung ignorieren, weil sie bald vergehen dürfte."],"explanation":"Gegenwärtige Wirkung und Beziehungsgeschichte sind unterschiedliche Daten.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 33; keine Originalaussage."},{"id":"book81-t15","chapterNo":34,"chapter":"Kapitel 34 · Beratungstransfer","topic":"Erwünschte Führung","track":"transfer","page":70,"question":"Eine Person wünscht sich im Intimleben mehr Initiative und zugleich klare Grenzen. Was passt?","answers":["Gemeinsam besprechen, welche Formen von Initiative erwünscht sind und wie Nein respektiert wird.","Eine pauschale Führungsrolle aufgrund des Geschlechts festlegen.","Spontanität als Begründung für fehlende Rückfrage verwenden.","Ab sofort nur noch die initiierende Person entscheiden lassen."],"explanation":"Die Form von Führung wird ausgehandelt, nicht vorausgesetzt.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 34; keine Originalaussage."},{"id":"book81-t16","chapterNo":35,"chapter":"Kapitel 35 · Beratungstransfer","topic":"Freiheit und Bindung","track":"transfer","page":74,"question":"Jemand sagt: „Ich fühle mich durch jede feste Verabredung eingeengt.“ Was würdest du differenzieren?","answers":["Was persönliche Freiheit bedeutet und welche Absprachen freiwillig tragbar sind.","Alle Absprachen abschaffen, weil maskuline Essenz frei sein müsse.","Den Wunsch nach Freiheit als Beweis für fehlende Liebe diagnostizieren.","Die Partnerperson auffordern, auf Verlässlichkeit zu verzichten."],"explanation":"Freiheit und Verbindlichkeit können ausgehandelt werden.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 35; keine Originalaussage."},{"id":"book81-t17","chapterNo":36,"chapter":"Kapitel 36 · Beratungstransfer","topic":"Fantasie und Grenzen","track":"transfer","page":76,"question":"Eine Person schämt sich für eine Fantasie, die sie keinesfalls ausleben möchte. Welche Unterscheidung hilft?","answers":["Fantasie, innere Bewertung und tatsächliches Handeln auseinanderhalten.","Die Fantasie als versteckte Verpflichtung zur Umsetzung sehen.","Die Person zur detaillierten Ausführung drängen.","Eine Fantasie direkt als Gefahr oder Störung diagnostizieren."],"explanation":"Das Anerkennen eines Impulses setzt keine Handlung voraus.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 36; keine Originalaussage."},{"id":"book81-t18","chapterNo":37,"chapter":"Kapitel 37 · Beratungstransfer","topic":"Stärke ohne Einschüchterung","track":"transfer","page":79,"question":"Ein Mann möchte „mehr Killer-Energie“, seine Partnerin fürchtet seine Wutausbrüche. Was ist sinnvoll?","answers":["Die Bedeutung von Stärke erkunden und die Angst vor Einschüchterung ernst nehmen.","Die Angst als Zeichen wirksamer Polarität feiern.","Zu stärkerer Konfrontation ermutigen, unabhängig von Wirkung.","Die Partnerin auffordern, sich an Wut zu gewöhnen."],"explanation":"Mut und Präsenz lassen sich nicht mit Bedrohung gleichsetzen.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 37; keine Originalaussage."},{"id":"book81-t19","chapterNo":38,"chapter":"Kapitel 38 · Beratungstransfer","topic":"Präsenz bei Übererregung","track":"transfer","page":81,"question":"In einem Streit steigern sich beide Personen immer weiter. Was sollte die Beratung zuerst ermöglichen?","answers":["Stopp- und Beruhigungsmöglichkeiten sowie die Bedingungen für weiteren Kontakt klären.","Die Intensität fortsetzen, damit sich Energie transformiert.","Eine Person für die Gefühlsregulation der anderen vollständig verantwortlich machen.","Den Konflikt sofort in erotisches Spiel überführen."],"explanation":"Erst bei genügender Sicherheit und Regulation kann Differenzierung gelingen.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 38; keine Originalaussage."},{"id":"book81-t20","chapterNo":40,"chapter":"Kapitel 40 · Beratungstransfer","topic":"Reife und Begehren","track":"transfer","page":85,"question":"Eine Person erlebt im Alter neue Anziehung, die nicht zu früheren Vorlieben passt. Was hilft?","answers":["Individuelle Veränderung würdigen statt normierende Altersregeln anzulegen.","Das Alter zur Entscheidungshilfe für erotische Eignung machen.","Nur jugendliche Beziehungsmodelle als gültig betrachten.","Die Erfahrung als Kompensation fehlender Jugend deuten."],"explanation":"Ausstrahlung und Lust sind individuell veränderlich.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 40; keine Originalaussage."},{"id":"book81-t21","chapterNo":42,"chapter":"Kapitel 42 · Beratungstransfer","topic":"Vorübergehender Lustverlust","track":"transfer","page":89,"question":"Nach einer Geburt hat ein Paar unterschiedlich viel Lust. Was wäre fachlich sinnvoll?","answers":["Schlaf, körperliche Veränderung, Druck und Beziehungskontext berücksichtigen.","Lustverlust unmittelbar als fehlende Polarität diagnostizieren.","Mehr Führung als allgemeine Lösung verschreiben.","Die geringere Lust als freiwilligen Beziehungsentzug behandeln."],"explanation":"Biologische und soziale Kontexte können zentraler sein als ein Polaritätsmodell.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 42; keine Originalaussage."},{"id":"book81-t22","chapterNo":44,"chapter":"Kapitel 44 · Beratungstransfer","topic":"Sexuelle Körperpraxis","track":"transfer","page":96,"question":"Ein Teilnehmer möchte eine Deida-Atem- und Orgasmustechnik als Therapie gegen Schmerzen anwenden. Was ist passend?","answers":["Auf fehlende klinische Absicherung hinweisen und gesundheitliche Beschwerden fachlich abklären lassen.","Die spirituelle Methode als medizinisch bestätigte Therapie anbieten.","Beschwerden als Zeichen mangelnder Hingabe interpretieren.","Zu forcierter Anwendung ohne körperliche Rückmeldung raten."],"explanation":"Spirituelle Erfahrung ersetzt keine medizinische Behandlung.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 44; keine Originalaussage."},{"id":"book81-t23","chapterNo":47,"chapter":"Kapitel 47 · Beratungstransfer","topic":"Mission der Frau","track":"transfer","page":108,"question":"Eine beruflich engagierte Frau setzt ihre Mission an erste Stelle, ihr Partner wünscht mehr Nähe. Wie reagierst du?","answers":["Beide Prioritäten erfragen, ohne sie anhand des Geschlechts für falsch zu erklären.","Ihre Lebensausrichtung als unweiblich bezeichnen.","Dem Mann jede Bedeutung von Bindung absprechen.","Eine feste maskuline und feminine Essenz diagnostizieren."],"explanation":"Individuelle Werte und Lebensphasen sind nicht an vorgegebene Geschlechterrollen gebunden.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 47; keine Originalaussage."},{"id":"book81-t24","chapterNo":48,"chapter":"Kapitel 48 · Beratungstransfer","topic":"Wer trägt die Beziehung?","track":"transfer","page":111,"question":"Ein Paar erwartet, dass einer allein Intimität „repariert“. Was reflektierst du?","answers":["Verantwortung, Handlungsspielräume und Belastung beider besprechen.","Dem männlichen Partner vollständige Kontrolle über das Beziehungserleben zusprechen.","Der anderen Person jede Eigenverantwortung abnehmen.","Intimität allein als Führungsproblem klassifizieren."],"explanation":"Zugewandte Initiative kann hilfreich sein, ohne eine Person für alle Gefühle zuständig zu machen.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 48; keine Originalaussage."},{"id":"book81-t25","chapterNo":49,"chapter":"Kapitel 49 · Beratungstransfer","topic":"Gemeinsames Wachstum","track":"transfer","page":114,"question":"Ein Partner fordert tägliche intime Übungen; die andere Person fühlt sich überfordert. Was muss gelten?","answers":["Ziele, Tempo und freiwillige Zustimmung gemeinsam klären.","Auf „Wachstum“ bestehen, unabhängig von Überforderung.","Ein Nein als Widerstand gegen Transformation werten.","Pflichtübungen ohne erneute Absprache einführen."],"explanation":"Wachstum ist kein Argument für Leistungsdruck oder Grenzverletzung.","source":"Eigene Transferaufgabe zu Deida (1997), Kapitel 49; keine Originalaussage."}];
